insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('f965addd-0f8d-45ba-b7d2-86ee6dd45ebe', 'N4', '尊敬語（Công thức dạng thể bị động）', 'Kính ngữ dùng thể bị động (受身形)', 'Thể bị động (受身形) của động từ cũng có thể dùng làm kính ngữ đơn giản, lịch sự vừa phải', 'V(thể bị động／受身形)', 'Dùng thể bị động của động từ để thể hiện sự tôn kính với chủ ngữ là người trên', NULL, NULL, NULL, '{}', NULL, 46, '尊敬語（Công thức dạng thể bị động）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('7d6a625d-0ac6-4a1c-aa0e-596b4d50ff67', 'N4', 'お＋Vます＋になります', 'Kính ngữ theo công thức お + gốc Vます + になります', 'Công thức tạo kính ngữ chung áp dụng được cho nhiều động từ (trừ nhóm có dạng đặc biệt riêng)', 'お + V(ます形 bỏ ます) + になります', 'Tạo dạng kính ngữ trang trọng cho hành động của người trên', NULL, NULL, NULL, '{}', NULL, 46, 'お＋Vます＋になります', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('88c3e97c-214d-43d3-8591-4a14f399d7a5', 'N4', 'お＋Vます＋ください', 'Kính ngữ mệnh lệnh lịch sự: xin vui lòng ~', 'Trang trọng, lịch sự hơn てください, dùng お trước gốc Vます', 'お + V(ます形 bỏ ます) + ください', 'Yêu cầu/mời ai đó làm gì một cách lịch sự, trang trọng', NULL, NULL, NULL, '{}', NULL, 46, 'お＋Vます＋ください', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('bb2ab841-f229-401b-bdf5-6491e0055084', 'N4', 'ご＋Vます＋ください', 'Kính ngữ mệnh lệnh lịch sự (dùng cho động từ Hán-Nhật gốc する): xin vui lòng ~', 'ご dùng thay お khi gốc Vます là từ Hán-Nhật (동사する)', 'ご + V(ます形 する→ bỏ する) + ください', 'Yêu cầu/mời ai đó làm gì một cách lịch sự, trang trọng, với động từ Hán-Nhật gốc する', NULL, NULL, NULL, '{}', NULL, 46, 'ご＋Vます＋ください', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('22fb3545-5c9d-41a7-a5d3-4579a9668271', 'N4', 'お＋Vます＋ですか', 'Kính ngữ hỏi trạng thái/sở hữu một cách lịch sự', 'Dạng rút gọn lịch sự, thường dùng với các động từ chỉ trạng thái/sở hữu', 'お + V(ます形 bỏ ます) + ですか', 'Hỏi ai đó về trạng thái/việc sở hữu một cách lịch sự', NULL, NULL, NULL, '{}', NULL, 46, 'お＋Vます＋ですか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('c2fabbd1-3261-42bf-9aa1-3ebd8b14b34a', 'N4', '謙譲語（Dạng đặc biệt của động từ）', 'Khiêm nhường ngữ đặc biệt: 呼びます／来ます／行きます／聞きます đổi thành dạng khiêm nhường riêng', 'Song song với 尊敬語 dạng đặc biệt, nhưng 謙譲語 dùng để hạ thấp hành động của bản thân khi nói với người trên', '呼びます→お呼びします／来ます→参ります／行きます→伺います／聞きます→伺います', NULL, NULL, NULL, NULL, '{}', NULL, 46, '謙譲語（Dạng đặc biệt của động từ）', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('6940f9c5-f64e-4236-8e54-f2b0f58c6102', 'c2fabbd1-3261-42bf-9aa1-3ebd8b14b34a', 1, '呼びます → お呼びします', '呼びます → お呼びします', NULL, NULL, 46, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('f7c94ada-d63b-4c3c-a16d-6dfa25ad1a50', 'c2fabbd1-3261-42bf-9aa1-3ebd8b14b34a', 2, '来ます → 参ります', '来ます → 参ります', NULL, NULL, 46, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('aab0f02a-fa6a-480c-a43c-432fcc99818e', 'c2fabbd1-3261-42bf-9aa1-3ebd8b14b34a', 3, '行きます → 伺います', '行きます → 伺います', NULL, NULL, 46, 'pdf');
